from rcb_client import Robot
import numpy as np, math, os
r=Robot(); q=np.array([0,1,0,0.]); now=np.array(r.get_obs(cameras=[],video='none').meta['proprio']['now'][7:10],float); rows=[]
def seg(a,b,step=.002):
 n=max(1,math.ceil(np.linalg.norm(np.array(b)-np.array(a))/step))
 for t in np.linspace(1/n,1,n): rows.append([*(np.array(a)*(1-t)+np.array(b)*t),*q])
def hold(p,n): rows.extend([[*p,*q]]*n)
# 2 mm press, 20 mm travel
p=[-.13,-.21,.018]; seg(now,[-.13,-.21,.065]); seg([-.13,-.21,.065],p); hold(p,10); seg(p,[-.11,-.21,.018]); hold([-.11,-.21,.018],4); seg([-.11,-.21,.018],[-.11,-.21,.065]);
# 5 mm press, disjoint practice location
seg([-.11,-.21,.065],[-.09,-.16,.065]); p2=[-.09,-.16,.015]; seg([-.09,-.16,.065],p2); hold(p2,10); seg(p2,[-.07,-.16,.015]); hold([-.07,-.16,.015],4); seg([-.07,-.16,.015],[-.07,-.16,.065]);
# clear the overhead practice view
seg([-.07,-.16,.065],[-.1,0,.15]);
os.makedirs('/app/output/calibration/shallow',exist_ok=True)
for k in range(0,len(rows),190):
 res=r.submit('ee_pose',np.asarray(rows[k:k+190],np.float32),dt=.05,video='mp4',video_fps=10,note='practice depth tests: 2mm and 5mm'); res.save(f'/app/output/calibration/shallow/chunk{k//190:02}')
 print('chunk',k//190,len(rows[k:k+190]),res.meta.get('executed_rows'),res.meta.get('proprio',{}).get('now',[None]*10)[7:10])
print('status',r.status())
from PIL import Image
o=r.get_obs(cameras=['practice_cam'],video='none'); Image.fromarray(o.last['practice_cam']).save('/app/output/calibration/practice_shallow.png')
